import Mathlib

def positionRow {N d : ℕ} (P : Fin N → Fin d → ℝ) (t : ℕ) : Option (Fin d → ℝ) :=
  if ht : 1 ≤ t ∧ t ≤ N then
    some (P ⟨t - 1, by omega⟩)
  else none

def embeddedRow {N d : ℕ} (P : Fin N → Fin d → ℝ) (symbol : Fin d → ℝ) (t : ℕ) : Option (Fin d → ℝ) :=
  (positionRow P t).map (fun row j => symbol j + row j)

def Claim : Prop :=
  ∀ (N d : ℕ) (P : Fin N → Fin d → ℝ) (symbol : Fin d → ℝ),
    embeddedRow P symbol (N + 1) = none
